create table if not exists benefit_plans (id uuid primary key default gen_random_uuid(), name text not null, provider text, coverage text, premium numeric(14,2), status text not null default 'Active', created_at timestamptz not null default now()); create table if not exists benefit_enrollments (id uuid primary key default gen_random_uuid(), plan_id uuid not null references benefit_plans(id), employee_id uuid not null references employees(id), status text not null default 'Active', created_at timestamptz not null default now()); create table if not exists dependents (id uuid primary key default gen_random_uuid(), employee_id uuid not null references employees(id), name text not null, relationship text not null, created_at timestamptz not null default now());
